// Generate Kubernetes-style manifests for a fleet of services.
local envs = ['dev', 'staging', 'prod'];
local regions = ['us-east1', 'europe-west4', 'asia-south1'];
local base = {
  apiVersion: 'apps/v1',
  kind: 'Deployment',
  name:: error 'name required',
  env:: 'dev',
  replicas:: 1,
  port:: 8080,
  labels:: { app: $.name, env: $.env, tier: 'backend' },
  metadata: { name: $.name + '-' + $.env, labels: $.labels },
  spec: {
    replicas: $.replicas,
    selector: { matchLabels: $.labels },
    template: {
      metadata: { labels: $.labels },
      spec: {
        containers: [{
          name: $.name,
          image: 'registry.example.com/%s:%s' % [$.name, std.md5($.name)[0:8]],
          ports: [{ containerPort: $.port }],
          env: [{ name: std.asciiUpper(k), value: std.toString($.settings[k]) } for k in std.objectFields($.settings)],
          resources: { limits: { cpu: '%dm' % (100 * $.replicas), memory: '%dMi' % (128 * $.replicas) } },
        }],
      },
    },
  },
  settings:: { LOG_LEVEL: if $.env == 'prod' then 'warn' else 'debug', PORT: $.port, REGION: 'none' },
};
local service(i, env, region) = base {
  name: 'svc-%04d' % i,
  env: env,
  replicas: if env == 'prod' then 3 + (i % 5) else 1,
  port: 8000 + (i % 100),
  settings+: { REGION: region, SHARD: i % 16, FEATURES: std.join(',', ['f%d' % j for j in std.range(0, i % 7)]) },
};
{
  ['%s/%s/svc-%04d.json' % [env, regions[i % 3], i]]: service(i, env, regions[i % 3])
  for i in std.range(1, 12)
  for env in envs
}

// Aggregate an imported order export into a per-customer report.
local data = import 'orders.json';
local byCustomer = std.foldl(
  function(acc, o) acc + { [o.customer]+: [o] },
  data.orders, {}
);
{
  customers: [
    {
      customer: c,
      orders: std.length(byCustomer[c]),
      total: std.foldl(function(s, o) s + std.foldl(function(t, it) t + it.qty * it.price, o.items, 0), byCustomer[c], 0),
      skus: std.sort(std.uniq(std.sort(std.flattenArrays([[it.sku for it in o.items] for o in byCustomer[c]])))),
      lastStatus: std.sort(byCustomer[c], function(o) o.id)[std.length(byCustomer[c]) - 1].status,
    }
    for c in std.objectFields(byCustomer)
  ],
  shipped: std.length([o for o in data.orders if o.status == 'shipped']),
  topOrders: [o.id for o in std.sort(data.orders, function(o) -std.length(o.items))[0:20]],
}

// Render a list of alerting rules as a YAML stream.
local sev = ['info', 'warning', 'critical'];
[
  {
    groups: [{
      name: 'team-%02d' % t,
      rules: [
        {
          alert: 'HighLatency%02d_%02d' % [t, r],
          expr: 'histogram_quantile(0.99, sum(rate(http_request_duration_seconds_bucket{team="%02d",route="/api/v%d"}[5m])) by (le)) > %0.2f' % [t, r % 3, 0.25 * (1 + r % 4)],
          'for': '%dm' % (5 * (1 + r % 3)),
          labels: { severity: sev[r % 3], team: 'team-%02d' % t },
          annotations: { summary: 'p99 latency above threshold for route %d' % r, runbook: 'https://runbooks.example.com/latency#%d' % r },
        }
        for r in std.range(0, 24)
      ],
    }],
  }
  for t in std.range(0, 0)
]

